pub fn attempt_transition_wire(t: Rc<AttemptTransition>) -> String {
    match (*t.clone()).clone() {
    AttemptTransition::AttemptAdvanced { state: s, generation: g, .. } => Rc::new(vec!["advanced to ".to_string(), attempt_state_wire(s.clone()), " at generation ".to_string(), (crate::std_durable_compare_and_set::cas_generation_count(g.clone())).to_string()]).join(&"".to_string()),
    AttemptTransition::AttemptLostRace { expected: e, observed: o, .. } => Rc::new(vec!["lost the race: expected ".to_string(), e.clone(), " and the slot holds ".to_string(), o.clone()]).join(&"".to_string()),
    AttemptTransition::AttemptTransitionRefused { detail: d, .. } => Rc::new(vec!["refused: ".to_string(), d.clone()]).join(&"".to_string()),
}
}

pub fn attempt_transition_advanced(t: Rc<AttemptTransition>) -> bool {
    match (*t.clone()).clone() {
    AttemptTransition::AttemptAdvanced { .. } => true,
    AttemptTransition::AttemptLostRace { .. } => false,
    AttemptTransition::AttemptTransitionRefused { detail: _, .. } => false,
}
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum RecoveryTrigger {
    RecoveryMayTerminate {
        reason: String,
    },
    RecoveryTooEarly {
        deadline: EpochSecs,
        now: EpochSecs,
    },
    RecoveryUnitNotEnded {
        lifecycle: Rc<UnitLifecycle>,
    },
    RecoveryTerminalRecordMayRelease {
        state: Rc<AttemptState>,
    },
}

pub fn recovery_trigger(record: Rc<AttemptRecord>, lifecycle: Rc<UnitLifecycle>, now: i64) -> Rc<RecoveryTrigger> {
    match (*record.state.clone()).clone() {
    AttemptState::AttemptReserved => if (now.clone() < record.launch_deadline.clone()) {
        Rc::new(RecoveryTrigger::RecoveryTooEarly {
    deadline: record.launch_deadline.clone(),
    now: now.clone(),
})
    } else {
        Rc::new(RecoveryTrigger::RecoveryMayTerminate {
    reason: Rc::new(vec!["the attempt declared a launch deadline of ".to_string(), (record.launch_deadline.clone()).to_string(), " and it is now ".to_string(), (now.clone()).to_string(), ", so the window the producer asked for has passed without a launch".to_string()]).join(&"".to_string()),
})
    },
    AttemptState::AttemptLaunching => if unit_lifecycle_ended(lifecycle.clone()) {
        Rc::new(RecoveryTrigger::RecoveryMayTerminate {
    reason: Rc::new(vec!["the unit is ".to_string(), unit_lifecycle_wire(lifecycle.clone())]).join(&"".to_string()),
})
    } else {
        Rc::new(RecoveryTrigger::RecoveryUnitNotEnded {
    lifecycle: lifecycle.clone(),
})
    },
    AttemptState::AttemptTerminal { verdict: v, detail: d, .. } => Rc::new(RecoveryTrigger::RecoveryTerminalRecordMayRelease {
    state: Rc::new(AttemptState::AttemptTerminal {
    verdict: v.clone(),
    detail: d.clone(),
}),
}),
}
}

pub fn recovery_trigger_fires(t: Rc<RecoveryTrigger>) -> bool {
    match (*t.clone()).clone() {
    RecoveryTrigger::RecoveryMayTerminate { reason: _, .. } => true,
    RecoveryTrigger::RecoveryTooEarly { .. } => false,
    RecoveryTrigger::RecoveryUnitNotEnded { lifecycle: _, .. } => false,
    RecoveryTrigger::RecoveryTerminalRecordMayRelease { state: _, .. } => false,
}
}

pub fn recovery_trigger_wire(t: Rc<RecoveryTrigger>) -> String {
    match (*t.clone()).clone() {
    RecoveryTrigger::RecoveryMayTerminate { reason: r, .. } => Rc::new(vec!["may terminate: ".to_string(), r.clone()]).join(&"".to_string()),
    RecoveryTrigger::RecoveryTooEarly { deadline: d, now: n, .. } => Rc::new(vec!["TOO EARLY: the attempt declared a launch deadline of ".to_string(), (d.clone()).to_string(), " and it is only ".to_string(), (n.clone()).to_string(), "; a producer inside its own declared window is not dead".to_string()]).join(&"".to_string()),
    RecoveryTrigger::RecoveryUnitNotEnded { lifecycle: u, .. } => Rc::new(vec!["the unit has not ended: ".to_string(), unit_lifecycle_wire(u.clone())]).join(&"".to_string()),
    RecoveryTrigger::RecoveryTerminalRecordMayRelease { state: s, .. } => Rc::new(vec!["the attempt is already ".to_string(), attempt_state_wire(s.clone()), ", so there is no transition to make; its seat is released only once the unit is proven ended".to_string()]).join(&"".to_string()),
}
}

#[derive(Clone)]
pub struct AttemptFencedCodec<P> {
    pub payload: Rc<AttemptPayloadCodec<P>>,
    pub claim_of: Rc<dyn Fn(P) -> Option<Rc<DurableHoldSubject>>>,
    pub with_claim: Rc<dyn Fn(P, Option<Rc<DurableHoldSubject>>) -> P>,
    pub change: Rc<dyn Fn(P) -> Option<P>>,
    pub advance: Rc<dyn Fn(P, Rc<AttemptState>) -> Option<P>>,
    pub _phantom: std::marker::PhantomData<P>,
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum AttemptFencedAction {
    AttemptClaimAcquire {
        owner: DurableHoldOwnerRef,
    },
    AttemptClaimRelease {
        lease: Rc<HeldLease>,
    },
    AttemptClaimRecover {
        report: Rc<DurableHoldHolderReport>,
    },
    AttemptOwnerAdvance {
        lease: Rc<HeldLease>,
        next: Rc<AttemptState>,
    },
    AttemptOwnerChange {
        lease: Rc<HeldLease>,
    },
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum AttemptFenceRefusal {
    AttemptFenceNoClaim,
    AttemptFenceWrongSubject,
    AttemptFenceWrongOwner,
    AttemptFenceWrongEpoch,
    AttemptFenceLeaseNotObserved,
    AttemptFenceOccupied,
    AttemptFenceRecoveryRefused,
    AttemptFenceStateRefused,
    AttemptFenceUnreadable {
        detail: String,
    },
    AttemptFenceGenerationExhausted,
}
impl AttemptFenceRefusal {
    pub fn detail(&self) -> String {
        match self {
            AttemptFenceRefusal::AttemptFenceNoClaim => panic!("no detail on unit variant"),
            AttemptFenceRefusal::AttemptFenceWrongSubject => panic!("no detail on unit variant"),
            AttemptFenceRefusal::AttemptFenceWrongOwner => panic!("no detail on unit variant"),
            AttemptFenceRefusal::AttemptFenceWrongEpoch => panic!("no detail on unit variant"),
            AttemptFenceRefusal::AttemptFenceLeaseNotObserved => panic!("no detail on unit variant"),
            AttemptFenceRefusal::AttemptFenceOccupied => panic!("no detail on unit variant"),
            AttemptFenceRefusal::AttemptFenceRecoveryRefused => panic!("no detail on unit variant"),
            AttemptFenceRefusal::AttemptFenceStateRefused => panic!("no detail on unit variant"),
            AttemptFenceRefusal::AttemptFenceUnreadable { detail: __val, .. } => __val.clone(),
            AttemptFenceRefusal::AttemptFenceGenerationExhausted => panic!("no detail on unit variant"),
        }
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
pub struct AttemptFencedWrite {
    store: Rc<SlotStore>,
    reference: NonEmptyStr,
    expected: CasGeneration,
    state: Rc<AttemptState>,
    payload: NonEmptyStr,
}
impl AttemptFencedWrite {
    pub fn store(&self) -> Rc<SlotStore> {
        self.store.clone()
    }
    pub fn reference(&self) -> NonEmptyStr {
        self.reference.clone()
    }
    pub fn expected(&self) -> CasGeneration {
        self.expected.clone()
    }
    pub fn state(&self) -> Rc<AttemptState> {
        self.state.clone()
    }
    pub fn payload(&self) -> NonEmptyStr {
        self.payload.clone()
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize)]
#[serde(tag = "_variant")]
pub enum AttemptFencedPreparation {
    AttemptFencePrepared {
        write: Rc<AttemptFencedWrite>,
    },
    AttemptFenceRefused {
        cause: Rc<AttemptFenceRefusal>,
    },
}

pub fn attempt_hold_ref(store: Rc<SlotStore>, reference: String) -> NonEmptyStr {
    crate::extdeps_languages_json_emit::serialize_json(crate::extdeps_languages_json_emit::json_object(Rc::new(vec![crate::extdeps_languages_json_emit::json_kv("store".to_string(), crate::extdeps_languages_json_emit::json_string(store.root())), crate::extdeps_languages_json_emit::json_kv("reference".to_string(), crate::extdeps_languages_json_emit::json_string(reference.clone()))])))
}

pub fn attempt_claim_lease(claim: Rc<DurableHoldSubject>, observed: HeldLeaseObservedState) -> Rc<HeldLease> {
    Rc::new(HeldLease {
    epoch: Rc::new(LeaseEpoch {
    lease_key: claim.hold.clone(),
    resource_fingerprint: crate::std_content_hash::content_hash_of_value(claim.hold.clone()),
    owner_fingerprint: crate::std_content_hash::content_hash_of_value(claim.holder.clone()),
    generation: claim.generation.clone(),
}),
    observed: observed.clone(),
})
}

pub fn attempt_fence_owner_refusal(claim: Option<Rc<DurableHoldSubject>>, hold: NonEmptyStr, lease: Rc<HeldLease>) -> Option<Rc<AttemptFenceRefusal>> {
    {
        let admitted = std::option::Option::None;
match claim.clone() {
    std::option::Option::None => Some(Rc::new(AttemptFenceRefusal::AttemptFenceNoClaim)),
    Some(c) => if ((c.hold.clone() != hold.clone()) || (lease.epoch.lease_key.clone() != hold.clone())) {
            Some(Rc::new(AttemptFenceRefusal::AttemptFenceWrongSubject))
        } else {
            if !match crate::std_content_hash::compare_content_hash(lease.epoch.resource_fingerprint.clone(), crate::std_content_hash::content_hash_of_value(hold.clone())) {
    ContentHashComparison::ContentHashEqual => true,
    _ => false,
} {
                Some(Rc::new(AttemptFenceRefusal::AttemptFenceWrongSubject))
            } else {
                if !match crate::std_content_hash::compare_content_hash(lease.epoch.owner_fingerprint.clone(), crate::std_content_hash::content_hash_of_value(c.holder.clone())) {
    ContentHashComparison::ContentHashEqual => true,
    _ => false,
} {
                    Some(Rc::new(AttemptFenceRefusal::AttemptFenceWrongOwner))
                } else {
                    if (crate::std_durable_compare_and_set::cas_generation_count(lease.epoch.generation.clone()) != crate::std_durable_compare_and_set::cas_generation_count(c.generation.clone())) {
                        Some(Rc::new(AttemptFenceRefusal::AttemptFenceWrongEpoch))
                    } else {
                        if !match lease.observed.clone() {
    HeldLeaseObservedState::LeaseRunningExpected => true,
    _ => false,
} {
                            Some(Rc::new(AttemptFenceRefusal::AttemptFenceLeaseNotObserved))
                        } else {
                            admitted
                        }
                    }
                }
            }
        },
}
}
}

pub fn attempt_state_transition_admitted(prior: Rc<AttemptState>, next: Rc<AttemptState>) -> bool {
    match (*next.clone()).clone() {
    AttemptState::AttemptReserved => false,
    AttemptState::AttemptLaunching => match (*prior.clone()).clone() {
    AttemptState::AttemptReserved => true,
    _ => false,
},
    AttemptState::AttemptTerminal { .. } => match (*prior.clone()).clone() {
    AttemptState::AttemptTerminal { .. } => false,
    _ => true,
},
}
}

pub fn attempt_fenced_proposal<P: Clone>(store: Rc<SlotStore>, reference: String, revision: i64, record: P, codec: Rc<AttemptFencedCodec<P>>) -> Rc<AttemptFencedPreparation> {
    Rc::new(AttemptFencedPreparation::AttemptFencePrepared {
    write: Rc::new(AttemptFencedWrite {
    store: store.clone(),
    reference: reference.clone(),
    expected: revision.clone(),
    state: (codec.payload.clone().state_of)(record.clone()),
    payload: (codec.payload.clone().encode)(record.clone()),
}),
})
}

pub fn attempt_fenced_decide<P: Clone>(store: Rc<SlotStore>, reference: String, revision: i64, record: P, codec: Rc<AttemptFencedCodec<P>>, action: Rc<AttemptFencedAction>) -> Rc<AttemptFencedPreparation> {
    {
        let claim = (codec.claim_of)(record.clone());
let hold = attempt_hold_ref(store.clone(), reference.clone());
match (*action.clone()).clone() {
    AttemptFencedAction::AttemptClaimAcquire { owner: owner, .. } => match claim.clone() {
    Some(_) => Rc::new(AttemptFencedPreparation::AttemptFenceRefused {
    cause: Rc::new(AttemptFenceRefusal::AttemptFenceOccupied),
}),
    std::option::Option::None => match (*crate::std_durable_compare_and_set::cas_generation_successor(revision.clone())).clone() {
    CasGenerationSuccessor::CasSuccessorExhausted { head: _, .. } => Rc::new(AttemptFencedPreparation::AttemptFenceRefused {
    cause: Rc::new(AttemptFenceRefusal::AttemptFenceGenerationExhausted),
}),
    CasGenerationSuccessor::CasSuccessorGeneration { generation: acquired, .. } => attempt_fenced_proposal(store.clone(), reference.clone(), revision.clone(), (codec.with_claim)(record.clone(), Some(Rc::new(DurableHoldSubject {
    hold: hold.clone(),
    holder: owner.clone(),
    generation: acquired.clone(),
}))), codec.clone()),
},
},
    AttemptFencedAction::AttemptClaimRecover { report: report, .. } => match claim.clone() {
    std::option::Option::None => Rc::new(AttemptFencedPreparation::AttemptFenceRefused {
    cause: Rc::new(AttemptFenceRefusal::AttemptFenceNoClaim),
}),
    Some(c) => if (c.hold.clone() != hold.clone()) {
            Rc::new(AttemptFencedPreparation::AttemptFenceRefused {
    cause: Rc::new(AttemptFenceRefusal::AttemptFenceWrongSubject),
})
        } else {
            match (*crate::std_durable_exclusive_hold::durable_hold_recovery_assess(Rc::new(DurableHoldObservation::HoldSlotHeld {
    generation: c.generation.clone(),
    owner: c.holder.clone(),
}), report.clone())).clone() {
    DurableHoldRecoveryAssessment::HoldRecoveryRefused { refusal: _, .. } => Rc::new(AttemptFencedPreparation::AttemptFenceRefused {
    cause: Rc::new(AttemptFenceRefusal::AttemptFenceRecoveryRefused),
}),
    DurableHoldRecoveryAssessment::HoldRecoveryEligible { .. } => attempt_fenced_proposal(store.clone(), reference.clone(), revision.clone(), (codec.with_claim)(record.clone(), std::option::Option::None), codec.clone()),
}
        },
},
    AttemptFencedAction::AttemptClaimRelease { lease: lease, .. } => match attempt_fence_owner_refusal(claim.clone(), hold.clone(), lease.clone()) {
    Some(cause) => Rc::new(AttemptFencedPreparation::AttemptFenceRefused {
    cause: cause.clone(),
}),
    std::option::Option::None => match claim.clone() {
    std::option::Option::None => Rc::new(AttemptFencedPreparation::AttemptFenceRefused {
    cause: Rc::new(AttemptFenceRefusal::AttemptFenceNoClaim),
}),
    Some(c) => match (*crate::std_durable_exclusive_hold::durable_hold_release_assess(Rc::new(DurableHoldObservation::HoldSlotHeld {
    generation: c.generation.clone(),
    owner: c.holder.clone(),
}), c.holder.clone(), lease.epoch.generation.clone())).clone() {
    DurableHoldReleaseAssessment::HoldReleaseRefused { refusal: _, .. } => Rc::new(AttemptFencedPreparation::AttemptFenceRefused {
    cause: Rc::new(AttemptFenceRefusal::AttemptFenceWrongEpoch),
}),
    DurableHoldReleaseAssessment::HoldReleaseEligible { generation: _, .. } => attempt_fenced_proposal(store.clone(), reference.clone(), revision.clone(), (codec.with_claim)(record.clone(), std::option::Option::None), codec.clone()),
},
},
},
    AttemptFencedAction::AttemptOwnerChange { lease: lease, .. } => match attempt_fence_owner_refusal(claim.clone(), hold.clone(), lease.clone()) {
    Some(cause) => Rc::new(AttemptFencedPreparation::AttemptFenceRefused {
    cause: cause.clone(),
}),
    std::option::Option::None => match (codec.change)(record.clone()) {
    std::option::Option::None => Rc::new(AttemptFencedPreparation::AttemptFenceRefused {
    cause: Rc::new(AttemptFenceRefusal::AttemptFenceStateRefused),
}),
    Some(changed) => attempt_fenced_proposal(store.clone(), reference.clone(), revision.clone(), changed.clone(), codec.clone()),
},
},
    AttemptFencedAction::AttemptOwnerAdvance { lease, next, .. } => match attempt_fence_owner_refusal(claim.clone(), hold.clone(), lease.clone()) {
    Some(cause) => Rc::new(AttemptFencedPreparation::AttemptFenceRefused {
    cause: cause.clone(),
}),
    std::option::Option::None => if attempt_state_transition_admitted((codec.payload.clone().state_of)(record.clone()), next.clone()) {
            match (codec.advance)(record.clone(), next.clone()) {
    std::option::Option::None => Rc::new(AttemptFencedPreparation::AttemptFenceRefused {
    cause: Rc::new(AttemptFenceRefusal::AttemptFenceStateRefused),
}),
    Some(changed) => attempt_fenced_proposal(store.clone(), reference.clone(), revision.clone(), changed.clone(), codec.clone()),
}
        } else {
            Rc::new(AttemptFencedPreparation::AttemptFenceRefused {
    cause: Rc::new(AttemptFenceRefusal::AttemptFenceStateRefused),
})
        },
},
}
}
}

